// Package repo is the backup repository format: its layout, its config and
// keys, packs, the index and snapshot manifests, over a store.Store.
//
// Every object but the wrapped data keys is sealed under a subkey of the
// repository data key (package seal). The data key is generated by Init,
// wrapped through the key seam, and stored wrapped; Open unwraps it into
// locked memory, and Close destroys it.
package repo

import (
	"context"
	"crypto/rand"
	"crypto/sha256"
	"encoding/json"
	"errors"

	"github.com/jeremyhahn/go-objstore/backup/pkg/chunker"
	"github.com/jeremyhahn/go-objstore/backup/pkg/keyseam"
	"github.com/jeremyhahn/go-objstore/backup/pkg/seal"
	"github.com/jeremyhahn/go-objstore/backup/pkg/store"
)

// Pack size bounds, in bytes.
const (
	// DefaultPackSize is the pack target size Init uses by default.
	DefaultPackSize = 16 << 20
	// MinPackSize is the smallest pack target size allowed.
	MinPackSize = 4 << 10
	// MaxPackSize is the largest pack target size allowed.
	MaxPackSize = 1 << 30
)

// formatVersion is the repository format version the config records.
const formatVersion = 1

// configID is the config's ID in its additional data.
var configID = []byte("config")

// Options are the settings Init records in the config.
type Options struct {
	// Chunker bounds the chunk sizes. The zero value means
	// chunker.DefaultParams.
	Chunker chunker.Params
	// PackSize is the size packs are filled to. Zero means DefaultPackSize.
	PackSize int
}

// Config is a repository's settings. It is sealed in the config object.
type Config struct {
	// Version is the repository format version.
	Version int `json:"version"`
	// ID is the repository's random ID.
	ID seal.ID `json:"id"`
	// Chunker bounds the chunk sizes.
	Chunker chunker.Params `json:"chunker"`
	// PackSize is the size packs are filled to.
	PackSize int `json:"pack_size"`
}

// validate checks the config's settings.
func (c Config) validate() error {
	if err := c.Chunker.Validate(); err != nil {
		return err
	}
	if c.PackSize < MinPackSize || c.PackSize > MaxPackSize {
		return errPackSize
	}
	return nil
}

var errPackSize = errors.New("pack size out of bounds")

// Repository is an open repository. Close it to destroy its keys. It is safe
// for concurrent use.
type Repository struct {
	st     store.Store
	layout Layout
	dk     *keyseam.DataKey
	keys   *seal.Keys
	cfg    Config
}

// Init creates a repository under prefix in st: it generates a data key,
// stores it wrapped by p, and writes the sealed config. It fails with
// ErrRepositoryExists if a config is already there, and ErrInvalidOptions
// for options out of bounds.
func Init(ctx context.Context, st store.Store, prefix string, p keyseam.Provider, opts Options) (*Repository, error) {
	const op = "init"
	cfg := Config{Version: formatVersion, Chunker: opts.Chunker, PackSize: opts.PackSize}
	if cfg.Chunker == (chunker.Params{}) {
		cfg.Chunker = chunker.DefaultParams()
	}
	if cfg.PackSize == 0 {
		cfg.PackSize = DefaultPackSize
	}
	if err := cfg.validate(); err != nil {
		return nil, newError(op, "", ErrInvalidOptions, err)
	}
	if _, err := rand.Read(cfg.ID[:]); err != nil {
		return nil, newError(op, "", ErrKeys, err)
	}
	layout := NewLayout(prefix)
	exists, err := st.Exists(ctx, layout.Config())
	if err != nil {
		return nil, fromStore(op, layout.Config(), err)
	}
	if exists {
		return nil, newError(op, layout.Config(), ErrRepositoryExists, nil)
	}

	dk, wrapped, err := keyseam.NewDataKey(ctx, p)
	if err != nil {
		return nil, newError(op, "", ErrKeys, err)
	}
	r, err := newRepository(st, layout, dk, cfg)
	if err != nil {
		return nil, err
	}
	keyName := layout.Name(KindKey, sha256.Sum256(wrapped))
	if err := st.Put(ctx, keyName, wrapped); err != nil {
		return nil, errors.Join(fromStore(op, keyName, err), r.Close())
	}
	plain, err := json.Marshal(cfg)
	if err != nil {
		return nil, errors.Join(newError(op, "", ErrCorrupt, err), r.Close())
	}
	sealed, err := r.keys.Seal(seal.TypeConfig, configID, seal.CompressionNone, plain)
	if err != nil {
		return nil, errors.Join(fromSeal(op, "", err), r.Close())
	}
	// The config goes last: a repository exists once its config does.
	if err := st.Put(ctx, layout.Config(), sealed); err != nil {
		return nil, errors.Join(fromStore(op, layout.Config(), err), r.Close())
	}
	return r, nil
}

// Open opens the repository under prefix in st with p. It tries each key
// object in turn; a key that p cannot unwrap, or that does not open the
// config, is passed over. It fails with ErrNoRepository if there is no
// config, and with ErrNoKey if no key opens it. In that case the error also
// matches the last key seam error, such as keyseam.ErrUnwrap for a wrong
// passphrase, and errors.As finds the *keyseam.Error.
func Open(ctx context.Context, st store.Store, prefix string, p keyseam.Provider) (*Repository, error) {
	const op = "open"
	layout := NewLayout(prefix)
	sealedCfg, err := st.Get(ctx, layout.Config())
	if errors.Is(err, store.ErrNotFound) {
		return nil, newError(op, layout.Config(), ErrNoRepository, err)
	}
	if err != nil {
		return nil, fromStore(op, layout.Config(), err)
	}
	names, err := st.List(ctx, layout.Dir(KindKey))
	if err != nil {
		return nil, fromStore(op, layout.Dir(KindKey), err)
	}
	var last error
	for _, name := range names {
		wrapped, err := st.Get(ctx, name)
		if err != nil {
			return nil, fromStore(op, name, err)
		}
		dk, err := keyseam.OpenDataKey(ctx, p, wrapped)
		if err != nil {
			if !errors.Is(err, keyseam.ErrUnwrap) && !errors.Is(err, keyseam.ErrMalformedWrappedKey) {
				return nil, newError(op, name, ErrKeys, err)
			}
			last = err
			continue
		}
		r, err := openWith(st, layout, dk, sealedCfg)
		if err == nil {
			return r, nil
		}
		if !errors.Is(err, seal.ErrOpen) {
			return nil, err
		}
		// This key unwraps but is not the repository's: another key object
		// may be.
		last = err
	}
	return nil, newError(op, layout.Dir(KindKey), ErrNoKey, last)
}

// openWith opens the sealed config with dk and returns the repository. It
// destroys dk on failure.
func openWith(st store.Store, layout Layout, dk *keyseam.DataKey, sealedCfg []byte) (*Repository, error) {
	const op = "open"
	r, err := newRepository(st, layout, dk, Config{})
	if err != nil {
		return nil, err
	}
	plain, err := r.keys.Open(seal.TypeConfig, configID, sealedCfg)
	if err != nil {
		return nil, errors.Join(fromSeal(op, layout.Config(), err), r.Close())
	}
	var cfg Config
	if err := json.Unmarshal(plain, &cfg); err != nil {
		return nil, errors.Join(newError(op, layout.Config(), ErrCorrupt, err), r.Close())
	}
	if cfg.Version != formatVersion {
		return nil, errors.Join(newError(op, layout.Config(), ErrCorrupt, nil), r.Close())
	}
	if err := cfg.validate(); err != nil {
		return nil, errors.Join(newError(op, layout.Config(), ErrCorrupt, err), r.Close())
	}
	r.cfg = cfg
	return r, nil
}

// newRepository derives the subkeys from dk. It destroys dk on failure.
func newRepository(st store.Store, layout Layout, dk *keyseam.DataKey, cfg Config) (*Repository, error) {
	keys, err := seal.DeriveKeys(dk.Handle())
	if err != nil {
		return nil, errors.Join(newError("derive keys", "", ErrKeys, err), dk.Close())
	}
	return &Repository{st: st, layout: layout, dk: dk, keys: keys, cfg: cfg}, nil
}

// Close destroys the data key and its subkeys. Every later operation that
// needs a key fails with ErrKeys.
func (r *Repository) Close() error {
	return errors.Join(r.keys.Close(), r.dk.Close())
}

// Config returns the repository's settings.
func (r *Repository) Config() Config {
	return r.cfg
}

// Layout returns the repository's object layout.
func (r *Repository) Layout() Layout {
	return r.layout
}

// ChunkID returns the chunk's ID under the repository's chunk-ID subkey.
func (r *Repository) ChunkID(data []byte) (seal.ID, error) {
	id, err := r.keys.ChunkID(data)
	if err != nil {
		return seal.ID{}, fromSeal("chunk id", "", err)
	}
	return id, nil
}
